        int peak = 0;
        long peakStart = 0L;
        long peakEnd = 0L;
        int idx = 0;
        while (idx < events.size()) {
            long time = events.get(idx)[0];
            while (idx < events.size() && events.get(idx)[0] == time) {
                current += (int) events.get(idx)[1];
                idx++;
            }
            if (current > peak) {
                peak = current;
                peakStart = time;
                peakEnd = idx < events.size() ? events.get(idx)[0] : time;
            } else if (current == peak && peak > 0 && time < peakEnd) {
                // 峰值区间被中间事件切断后再次达到峰值时不延展；保留首次峰值区间即可
            }
        }
        // 若首次达到峰值后直到更晚时刻仍维持峰值，peakEnd 需要延展到回落时刻
        peakEnd = resolvePlateauEnd(events, peakStart, peak);
        return new Peak(peak, peakStart, peakEnd);
    }

    /**
     * 从首次达到峰值的事件时刻起，找到并发首次低于峰值的事件时刻作为峰值区间右端（不含）。
