        assertThat(newDwell.get("minDwellMinutes").asInt()).isEqualTo(10);
        assertThat(newDwell.get("platformCapacity").asInt()).isEqualTo(3);
        assertThat(newDwell.get("actualDwellMinutes").asInt()).isEqualTo(10);
    }

